// ── DASHBOARD ─────────────────────────────────────────────────────────────────
function Dashboard({ properties, transactions, bookings, tc, pinnedValues, pinValue }) {
  const [nights,setNights]=useState(pinnedValues?.nights||12);
  const now=new Date();
  const d1=properties.find(p=>p.type==="fixed_rental"||p.type==="fija");
  const d2=properties.find(p=>p.type==="short_term"||p.type==="short-term"||p.type==="temporal");

  const inc1ARS = d1 ? (transactions.filter(t=>t.propertyId===d1.id&&t.type==="income").reduce((s,t)=>s+t.amountARS,0)/3||476670) : 476670;
  const inc1USD=arsToUsd(inc1ARS,tc), net1USD=inc1USD, val1=d1?.estimatedValueUSD||67000;
  const cap1=val1>0?(net1USD*12/val1)*100:0, pb1=net1USD>0?val1/(net1USD*12):null;

  const inc2ARS=70000*nights, inc2USD=arsToUsd(inc2ARS,tc);
  const exp2ARS=pinnedValues?.gastosMensuales||80000, exp2USD=arsToUsd(exp2ARS,tc);
  const net2USD=inc2USD-exp2USD, val2=d2?.estimatedValueUSD||57000;
  const cap2=val2>0&&net2USD>0?(net2USD*12/val2)*100:0, pb2=net2USD>0?val2/(net2USD*12):null;

  const totalVal=val1+val2, totalNet=net1USD+net2USD, totalInc=inc1USD+inc2USD;
  const netYield=totalVal>0?(totalNet*12/totalVal)*100:0;
  const irr=calcIRR(totalVal,totalNet*12,totalVal,20);

  const projection=Array.from({length:20},(_,i)=>({
    year:i+1, cum:Math.round(-totalVal+totalNet*12*(i+1)),
    recovered:-totalVal+totalNet*12*(i+1)>=0,
  }));
  const pbYear=projection.find(r=>r.recovered)?.year;
  const maxAbs=Math.max(...projection.map(r=>Math.abs(r.cum)),1);
  const recentTxs=transactions.slice(0,6);
  const last6=Array.from({length:6},(_,i)=>{
    const d=new Date(now.getFullYear(),now.getMonth()-(5-i),1);
    const ms=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
    const inc=transactions.filter(t=>t.type==="income"&&t.date?.startsWith(ms)).reduce((s,t)=>s+t.amountUSD,0);
    return { month:MONTHS_SHORT[d.getMonth()], inc:inc||(i===5?inc1USD+inc2USD:0) };
  });
  const maxBar=Math.max(...last6.map(m=>m.inc),1);

  return (
    <div style={{ animation:"fadeIn 0.25s ease" }}>
      <div style={{ marginBottom:32 }}>
        <h1 style={{ fontSize:26, fontWeight:800, letterSpacing:"-0.5px" }}>
          {now.getHours()<12?"Buenos días":now.getHours()<19?"Buenas tardes":"Buenas noches"} 👋
        </h1>
        <p style={{ color:C.textSec, fontSize:14, marginTop:5 }}>
          {now.toLocaleDateString("es-AR",{weekday:"long",day:"numeric",month:"long",year:"numeric"})}
          {" · "}<span style={{ color:C.green, fontWeight:600 }}>TC ${tc.toLocaleString("es-AR")}</span>
        </p>
      </div>

      <div className="grid-4" style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:14, marginBottom:20 }}>
        {[
          { label:"Valor del portfolio", value:fUSD(totalVal), sub:`${properties.length} propiedades`, accent:C.text },
          { label:"Ingreso neto / mes",  value:fUSD(totalNet), sub:`bruto ${fUSD(totalInc)}`,          accent:C.green },
          { label:"Rentabilidad neta",   value:fPct(netYield), sub:"anual en USD",                     accent:netYield>4?C.green:C.yellow },
          { label:"TIR estimada",        value:fPct(irr),      sub:"proyección 20 años",               accent:irr>6?C.green:irr>3?C.yellow:C.red },
        ].map(({label,value,sub,accent})=>(
          <div key={label} style={S.card}>
            <div style={{ fontSize:11, color:C.textMuted, fontWeight:600, letterSpacing:"0.4px", marginBottom:10, textTransform:"uppercase" }}>{label}</div>
            <div style={{ fontSize:24, fontWeight:800, color:accent, letterSpacing:"-0.5px" }}>{value}</div>
            <div style={{ fontSize:12, color:C.textMuted, marginTop:4 }}>{sub}</div>
          </div>
        ))}
      </div>

      <div className="grid-2" style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:16 }}>
        <div style={{ ...S.card, borderTop:"3px solid "+C.green }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:18 }}>
            <div>
              <div style={{ fontSize:15, fontWeight:700 }}>{d1?.name||"Depto 1 · Renta Fija"}</div>
              <div style={{ fontSize:12, color:C.textSec, marginTop:2 }}>1 dorm · 2 ambientes grandes · Sin gastos</div>
            </div>
            <span style={{ fontSize:11, background:C.greenLight, color:C.green, padding:"3px 10px", borderRadius:20, fontWeight:600 }}>Alquilado</span>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:14 }}>
            {[
              { label:"Ingreso bruto/mes", value:fARS(inc1ARS), sub:fUSD(inc1USD) },
              { label:"Neto/mes",          value:fUSD(net1USD), color:C.green, sub:"sin gastos" },
              { label:"Valor propiedad",   value:fUSD(val1) },
              { label:"Cap Rate",          value:fPct(cap1), color:cap1>4?C.green:C.yellow },
            ].map(({label,value,sub,color})=>(
              <div key={label} style={{ background:C.bg, borderRadius:10, padding:"10px 12px" }}>
                <div style={{ fontSize:10, color:C.textMuted, textTransform:"uppercase", letterSpacing:"0.4px", marginBottom:4, fontWeight:500 }}>{label}</div>
                <div style={{ fontSize:15, fontWeight:700, color:color||C.text }}>{value}</div>
                {sub&&<div style={{ fontSize:10, color:C.textMuted, marginTop:2 }}>{sub}</div>}
              </div>
            ))}
          </div>
          <div style={{ display:"flex", justifyContent:"space-between", background:C.greenLight, borderRadius:10, padding:"10px 14px" }}>
            <span style={{ fontSize:13, color:C.green, fontWeight:500 }}>Payback</span>
            <span style={{ fontSize:14, fontWeight:800, color:C.green }}>{pb1?pb1.toFixed(1)+" años":"N/A"}</span>
          </div>
        </div>

        <div style={{ ...S.card, borderTop:"3px solid "+C.yellow }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:14 }}>
            <div>
              <div style={{ fontSize:15, fontWeight:700 }}>{d2?.name||"Depto 2 · Renta Temporal"}</div>
              <div style={{ fontSize:12, color:C.textSec, marginTop:2 }}>1 dorm · 2 ambientes chicos</div>
            </div>
            <span style={{ fontSize:11, background:C.yellowLight, color:C.yellow, padding:"3px 10px", borderRadius:20, fontWeight:600 }}>Por día</span>
          </div>
          <div style={{ background:C.yellowLight, borderRadius:10, padding:"10px 14px", marginBottom:12 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6 }}>
              <span style={{ fontSize:12, color:C.yellow, fontWeight:500 }}>Noches estimadas / mes</span>
              <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                <span style={{ fontSize:13, fontWeight:700, color:C.yellow }}>{nights} · {Math.round(nights/30*100)}%</span>
                <PinBtn pinKey="nights" value={nights} pinnedValues={pinnedValues} pinValue={pinValue}/>
              </div>
            </div>
            <input type="range" min={0} max={30} value={nights} onChange={e=>setNights(Number(e.target.value))} style={{ width:"100%", accentColor:C.yellow, cursor:"pointer" }}/>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:14 }}>
            {[
              { label:"Ingreso est./mes", value:fARS(inc2ARS), sub:fUSD(inc2USD) },
              { label:"Neto/mes",         value:fUSD(net2USD), color:net2USD>0?C.green:C.red },
              { label:"Gastos fijos",     value:fARS(exp2ARS), color:C.red, sub:fUSD(exp2USD) },
              { label:"Cap Rate",         value:cap2>0?fPct(cap2):"—", color:cap2>4?C.green:C.yellow },
            ].map(({label,value,sub,color})=>(
              <div key={label} style={{ background:C.bg, borderRadius:10, padding:"10px 12px" }}>
                <div style={{ fontSize:10, color:C.textMuted, textTransform:"uppercase", letterSpacing:"0.4px", marginBottom:4, fontWeight:500 }}>{label}</div>
                <div style={{ fontSize:15, fontWeight:700, color:color||C.text }}>{value}</div>
                {sub&&<div style={{ fontSize:10, color:C.textMuted, marginTop:2 }}>{sub}</div>}
              </div>
            ))}
          </div>
          <div style={{ display:"flex", justifyContent:"space-between", background:C.yellowLight, borderRadius:10, padding:"10px 14px" }}>
            <span style={{ fontSize:13, color:C.yellow, fontWeight:500 }}>Payback</span>
            <span style={{ fontSize:14, fontWeight:800, color:C.yellow }}>{pb2?pb2.toFixed(1)+" años":"Negativo"}</span>
          </div>
        </div>
      </div>

      <div className="grid-2" style={{ display:"grid", gridTemplateColumns:"1.5fr 1fr", gap:16, marginBottom:16 }}>
        <div style={S.card}>
          <div style={{ fontSize:15, fontWeight:700, marginBottom:4 }}>Ingresos últimos 6 meses</div>
          <div style={{ fontSize:12, color:C.textSec, marginBottom:20 }}>En USD</div>
          <div style={{ display:"flex", alignItems:"flex-end", gap:10, height:130 }}>
            {last6.map((m,i)=>(
              <div key={i} style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", gap:6 }}>
                <div style={{ width:"100%", height:100, display:"flex", alignItems:"flex-end" }}>
                  <div style={{ width:"100%", minHeight:4, height:`${(m.inc/maxBar)*100}%`, background:i===5?`linear-gradient(to top,${C.blue},#3b82f6)`:C.border, borderRadius:"6px 6px 0 0", transition:"height 0.4s" }} title={fUSD(m.inc)}/>
                </div>
                <span style={{ fontSize:11, color:i===5?C.text:C.textMuted, fontWeight:i===5?600:400 }}>{m.month}</span>
              </div>
            ))}
          </div>
        </div>
        <div style={S.card}>
          <div style={{ fontSize:15, fontWeight:700, marginBottom:4 }}>Recupero de inversión</div>
          <div style={{ fontSize:12, color:C.textSec, marginBottom:16 }}>20 años · {fUSD(totalVal)}</div>
          <div style={{ display:"flex", alignItems:"flex-end", gap:2, height:90, marginBottom:14 }}>
            {projection.map((r,i)=>{
              const pct=Math.abs(r.cum)/maxAbs*100;
              const isPayback=r.recovered&&!projection[i-1]?.recovered;
              return (
                <div key={r.year} style={{ flex:1, height:"100%", display:"flex", alignItems:"flex-end" }}>
                  <div style={{ width:"100%", minHeight:3, height:`${Math.max(pct,3)}%`, borderRadius:"3px 3px 0 0", background:isPayback?C.green:r.recovered?C.greenLight:"#fee2e2" }} title={`Año ${r.year}: ${fUSD(r.cum)}`}/>
                </div>
              );
            })}
          </div>
          {pbYear ? (
            <div style={{ background:C.greenLight, borderRadius:10, padding:"10px 14px" }}>
              <div style={{ fontSize:13, fontWeight:700, color:C.green }}>✓ Recupero en año {pbYear}</div>
              <div style={{ fontSize:11, color:C.textSec, marginTop:2 }}>TIR {fPct(irr)} · Neto {fUSD(totalNet)}/mes</div>
            </div>
          ) : (
            <div style={{ background:C.redLight, borderRadius:10, padding:"10px 14px" }}>
              <div style={{ fontSize:12, color:C.red, fontWeight:500 }}>No se recupera en 20 años. Revisá Punto de Equilibrio.</div>
            </div>
          )}
        </div>
      </div>

      {recentTxs.length>0&&(
        <div style={S.card}>
          <div style={{ fontSize:15, fontWeight:700, marginBottom:18 }}>Actividad reciente</div>
          {recentTxs.map((t,i)=>(
            <div key={t.id} style={{ display:"flex", alignItems:"center", gap:14, padding:"12px 0", borderBottom:i<recentTxs.length-1?"1px solid "+C.border:"none" }}>
              <div style={{ width:36, height:36, borderRadius:10, flexShrink:0, background:t.type==="income"?C.greenLight:C.redLight, display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, color:t.type==="income"?C.green:C.red }}>
                {t.type==="income"?"↑":"↓"}
              </div>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:14, fontWeight:500 }}>{t.description}</div>
                <div style={{ fontSize:12, color:C.textMuted, marginTop:2 }}>{t.date}</div>
              </div>
              <div style={{ textAlign:"right" }}>
                <div style={{ fontSize:14, fontWeight:700, color:t.type==="income"?C.green:C.red }}>{t.type==="income"?"+":"−"}{fUSD(t.amountUSD)}</div>
                <div style={{ fontSize:11, color:C.textMuted }}>{fARS(t.amountARS)}</div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── PUNTO DE EQUILIBRIO ───────────────────────────────────────────────────────
function Equilibrio({ tc, pinnedValues, pinValue }) {
  const defaultGastos = [
    { id:1, nombre:"Internet",             monto:15000 },
    { id:2, nombre:"Expensas",             monto:45000 },
    { id:3, nombre:"Limpieza por estadía", monto:8000  },
    { id:4, nombre:"Otros",               monto:5000  },
  ];

  function parseGastos(pv) {
    if (!pv) return defaultGastos;
    const raw = pv["gastos"];
    if (!raw) return defaultGastos;
    try {
      const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    } catch(e) { console.error("parseGastos error:", e); }
    return defaultGastos;
  }

  const [gastos,setGastos]=useState(() => parseGastos(pinnedValues));
  const [nuevoNombre,setNuevoNombre]=useState("");
  const [nuevoMonto,setNuevoMonto]=useState("");
  const [targetGanancia,setTargetGanancia]=useState(pinnedValues?.targetGanancia||200);
  const [commAirbnb,setCommAirbnb]=useState(pinnedValues?.commAirbnb||15);
  const [commBooking,setCommBooking]=useState(pinnedValues?.commBooking||15);
  const [platform,setPlatform]=useState("direct");
  const [gastosSaved,setGastosSaved]=useState(false);

  const commPct = platform==="airbnb"?commAirbnb:platform==="booking"?commBooking:0;
  const totalGastosARS=gastos.reduce((s,g)=>s+g.monto,0);
  const totalGastosUSD=arsToUsd(totalGastosARS,tc);
  const ingresoNecesarioARS=(totalGastosUSD+targetGanancia)*tc;

  async function saveGastos() {
    try {
      const cleanGastos = gastos.map((g, i) => ({
        id: i + 1,
        nombre: String(g.nombre || ""),
        monto: Number(g.monto || 0),
      }));
      await pinValue("gastos", JSON.stringify(cleanGastos));
      await pinValue("targetGanancia", Number(targetGanancia));
      setGastosSaved(true);
      setTimeout(()=>setGastosSaved(false), 2500);
    } catch(e) {
      console.error("saveGastos error:", e);
      alert("Error al guardar gastos: " + e.message);
    }
  }

  function agregarGasto() {
    if(!nuevoNombre||!nuevoMonto) return;
    const newId = gastos.length + 1;
    setGastos([...gastos, {id: newId, nombre: String(nuevoNombre), monto: Number(nuevoMonto)}]);
    setNuevoNombre(""); setNuevoMonto("");
    setGastosSaved(false);
  }

  const escenarios=[5,8,10,12,15,20,25].map(noches=>{
    const cleaningFeeTotal=15000*Math.ceil(noches/3);
    const brutoNecesario=Math.ceil((ingresoNecesarioARS+cleaningFeeTotal)/(1-commPct/100)/noches/1000)*1000;
    const ingresoBruto=brutoNecesario*noches+cleaningFeeTotal;
    const comision=Math.round(ingresoBruto*commPct/100);
    const ingresoNeto=ingresoBruto-comision;
    const gananciaUSD=arsToUsd(ingresoNeto-totalGastosARS-cleaningFeeTotal,tc);
    return { noches, brutoNecesario, ingresoBruto, comision, ingresoNeto, cleaningFeeTotal, gananciaUSD, ocupacion:Math.round(noches/30*100) };
  });

  return (
    <div style={{animation:"fadeIn 0.25s ease"}}>
      <div style={{marginBottom:32}}>
        <h1 style={{fontSize:26,fontWeight:800,letterSpacing:"-0.5px"}}>Punto de equilibrio</h1>
        <p style={{color:C.textSec,fontSize:14,marginTop:5}}>Depto 2 · ¿Cuánto cobrar y cuántas noches necesitás?</p>
      </div>

      <div style={{...S.card,marginBottom:20}}>
        <div style={{fontSize:15,fontWeight:700,marginBottom:16}}>Comisiones de plataformas</div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:14}}>
          {[
            {key:"airbnb",  label:"Airbnb",  val:commAirbnb,  set:setCommAirbnb,  color:"#ff5a5f",pinKey:"commAirbnb"},
            {key:"booking", label:"Booking", val:commBooking, set:setCommBooking, color:"#003580",pinKey:"commBooking"},
            {key:"direct",  label:"Directa", val:0,           set:null,           color:C.green,  pinKey:null},
          ].map(({key,label,val,set,color,pinKey})=>(
            <div key={key} onClick={()=>setPlatform(key)} style={{background:platform===key?C.bg:C.white,border:`2px solid ${platform===key?color:C.border}`,borderRadius:12,padding:"14px 16px",cursor:"pointer"}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
                <div style={{fontSize:14,fontWeight:700,color}}>{label}</div>
                {platform===key&&<span style={{fontSize:10,background:color+"22",color,padding:"2px 8px",borderRadius:20,fontWeight:600}}>Activo</span>}
              </div>
              {set?(
                <div style={{display:"flex",alignItems:"center",gap:6}}>
                  <input type="number" value={val} min={0} max={30} onChange={e=>set(Number(e.target.value))} style={{...S.input,width:60,textAlign:"center",fontWeight:700,fontSize:16,padding:"6px 8px"}}/>
                  <span style={{fontSize:14,color:C.textSec}}>%</span>
                  {pinKey&&<PinBtn pinKey={pinKey} value={val} pinnedValues={pinnedValues} pinValue={pinValue}/>}
                </div>
              ):(
                <div style={{fontSize:18,fontWeight:700,color:C.green}}>0%</div>
              )}
              <div style={{fontSize:11,color:C.textMuted,marginTop:4}}>{key==="direct"?"Sin comisión":`Descuento del ${val}% sobre el total`}</div>
            </div>
          ))}
        </div>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1.5fr",gap:20}}>
        <div style={S.card}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
            <div style={{fontSize:15,fontWeight:700}}>Gastos fijos mensuales</div>
            <button onClick={saveGastos} style={{
              background:gastosSaved?C.green:C.blue, color:"#fff", border:"none",
              borderRadius:8, padding:"6px 14px", fontSize:12, fontWeight:600, cursor:"pointer",
              display:"flex", alignItems:"center", gap:6,
            }}>
              📌 {gastosSaved?"¡Guardado!":"Guardar gastos"}
            </button>
          </div>
          <div style={{fontSize:12,color:C.textSec,marginBottom:16}}>Costos del Depto 2 por mes</div>

          <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:14}}>
            {gastos.map(g=>(
              <div key={g.id} style={{display:"flex",alignItems:"center",gap:8}}>
                <input value={g.nombre} onChange={e=>{ setGastos(gastos.map(x=>x.id===g.id?{...x,nombre:e.target.value}:x)); setGastosSaved(false); }} style={{...S.input,flex:1,fontSize:13}}/>
                <div style={{position:"relative"}}>
                  <span style={{position:"absolute",left:10,top:"50%",transform:"translateY(-50%)",color:C.textMuted,fontSize:13}}>$</span>
                  <input type="number" value={g.monto} onChange={e=>{ setGastos(gastos.map(x=>x.id===g.id?{...x,monto:Number(e.target.value)}:x)); setGastosSaved(false); }} style={{...S.input,width:100,paddingLeft:22,fontSize:13}}/>
                </div>
                <button onClick={()=>saveGastos()} title="Guardar este gasto" style={{background:C.greenLight,border:"none",color:C.green,borderRadius:8,width:34,height:38,cursor:"pointer",fontSize:14,flexShrink:0,fontWeight:700}}>💾</button>
                <button onClick={()=>{ setGastos(gastos.filter(x=>x.id!==g.id)); }} style={{background:C.redLight,border:"none",color:C.red,borderRadius:8,width:32,height:38,cursor:"pointer",fontSize:16,flexShrink:0}}>×</button>
              </div>
            ))}
          </div>

          <div style={{display:"flex",gap:8,marginBottom:16,paddingTop:10,borderTop:"1px solid "+C.border}}>
            <input value={nuevoNombre} onChange={e=>setNuevoNombre(e.target.value)} style={{...S.input,flex:1,fontSize:13}} placeholder="Nuevo gasto..."/>
            <div style={{position:"relative"}}>
              <span style={{position:"absolute",left:10,top:"50%",transform:"translateY(-50%)",color:C.textMuted,fontSize:13}}>$</span>
              <input type="number" value={nuevoMonto} onChange={e=>setNuevoMonto(e.target.value)} onKeyDown={e=>e.key==="Enter"&&agregarGasto()} style={{...S.input,width:110,paddingLeft:22,fontSize:13}} placeholder="0"/>
            </div>
            <button onClick={agregarGasto} style={{...S.btnGreen,padding:"10px 14px",flexShrink:0}}>+</button>
          </div>

          <div style={{background:C.bg,borderRadius:12,padding:14,border:"1px solid "+C.border,marginBottom:14}}>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:8}}>
              <span style={{fontSize:13,color:C.textSec}}>Total gastos / mes</span>
              <span style={{fontSize:15,fontWeight:700,color:C.red}}>{fARS(totalGastosARS)}</span>
            </div>
            <div style={{display:"flex",justifyContent:"space-between"}}>
              <span style={{fontSize:13,color:C.textSec}}>En USD</span>
              <span style={{fontSize:15,fontWeight:700,color:C.red}}>{fUSD(totalGastosUSD)}</span>
            </div>
          </div>

          <div style={{background:C.greenLight,borderRadius:12,padding:14}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
              <span style={{fontSize:13,fontWeight:600,color:C.green}}>Ganancia neta deseada</span>
              <PinBtn pinKey="targetGanancia" value={targetGanancia} pinnedValues={pinnedValues} pinValue={pinValue}/>
            </div>
            <div style={{display:"flex",alignItems:"center",gap:6}}>
              <span style={{fontSize:14,color:C.green,fontWeight:700}}>USD</span>
              <input type="number" value={targetGanancia} onChange={e=>{ setTargetGanancia(Number(e.target.value)); setGastosSaved(false); }} style={{...S.input,fontSize:20,fontWeight:800,color:C.green,border:"none",background:"transparent",width:100}}/>
              <span style={{fontSize:12,color:C.green}}>/mes</span>
            </div>
            <div style={{fontSize:11,color:C.green,opacity:0.8,marginTop:4}}>= {fARS(targetGanancia*tc)} ARS/mes</div>
          </div>
        </div>

        <div style={S.card}>
          <div style={{fontSize:15,fontWeight:700,marginBottom:4}}>¿Cuánto cobrar por noche?</div>
          <div style={{fontSize:12,color:C.textSec,marginBottom:16}}>
            Plataforma: <strong>{platform==="direct"?"Directa":platform==="airbnb"?"Airbnb":"Booking"}</strong>
            {commPct>0&&<span style={{color:C.red}}> (−{commPct}% comisión)</span>}
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:8}}>
            {escenarios.map(e=>{
              const esRentable=e.gananciaUSD>=targetGanancia*0.9;
              const esOptimo=e.noches===12;
              return (
                <div key={e.noches} style={{display:"grid",gridTemplateColumns:"48px 1fr 1fr 1fr 70px",alignItems:"center",gap:10,padding:"11px 14px",borderRadius:12,background:esOptimo?C.bg:"transparent",border:`1px solid ${esOptimo?C.borderMed:C.border}`}}>
                  <div style={{textAlign:"center"}}>
                    <div style={{fontSize:17,fontWeight:800,color:esRentable?C.text:C.textMuted}}>{e.noches}</div>
                    <div style={{fontSize:9,color:C.textMuted}}>noches</div>
                  </div>
                  <div>
                    <div style={{fontSize:10,color:C.textMuted,marginBottom:2}}>Precio/noche</div>
                    <div style={{fontSize:14,fontWeight:700}}>{fARS(e.brutoNecesario)}</div>
                    {commPct>0&&<div style={{fontSize:10,color:C.red}}>Com: {fARS(e.comision)}</div>}
                  </div>
                  <div>
                    <div style={{fontSize:10,color:C.textMuted,marginBottom:2}}>Ingreso neto</div>
                    <div style={{fontSize:13,fontWeight:600}}>{fARS(e.ingresoNeto)}</div>
                    <div style={{fontSize:10,color:C.textMuted}}>{e.ocupacion}% ocupación</div>
                  </div>
                  <div>
                    <div style={{fontSize:10,color:C.textMuted,marginBottom:2}}>Ganancia</div>
                    <div style={{fontSize:14,fontWeight:700,color:esRentable?C.green:C.red}}>{fUSD(e.gananciaUSD)}</div>
                  </div>
                  <div style={{textAlign:"right"}}>
                    {esRentable
                      ?<span style={{fontSize:11,background:C.greenLight,color:C.green,padding:"3px 8px",borderRadius:20,fontWeight:600}}>✓ OK</span>
                      :<span style={{fontSize:11,background:C.redLight,color:C.red,padding:"3px 8px",borderRadius:20,fontWeight:600}}>Bajo</span>}
                  </div>
                </div>
              );
            })}
          </div>
          <div style={{marginTop:14,padding:"12px 16px",background:C.blueLight,borderRadius:12}}>
            <div style={{fontSize:13,fontWeight:600,color:C.blueMid,marginBottom:4}}>💡 Recomendación</div>
            <div style={{fontSize:13,color:C.blue}}>
              Con {escenarios.find(e=>e.gananciaUSD>=targetGanancia)?.noches||"más"} noches/mes superás tu meta de {fUSD(targetGanancia)}.
              {commPct>0&&` Recordá que ${platform==="airbnb"?"Airbnb":"Booking"} cobra el ${commPct}% de comisión.`}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── PROPIEDADES ───────────────────────────────────────────────────────────────
function Properties({ properties, transactions, tc, reload, db, pinnedValues, pinValue, setPage }) {
  const [showForm,setShowForm]=useState(false);
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState("");
  const [editingId,setEditingId]=useState(null);
  const [editValues,setEditValues]=useState({});
  const [form,setForm]=useState({ name:"", type:"fixed_rental", address:"", bedrooms:1, sqm:0, estimatedValueUSD:0, purchasePriceUSD:0, monthlyIncomeARS:0, monthlyExpensesARS:0, status:"rented", description:"" });
  function setF(f,v){setForm(p=>({...p,[f]:v}));}

  async function save() {
    if(!form.name){setError("El nombre es obligatorio.");return;}
    setSaving(true);setError("");
    try {
      await addDoc(collection(db,"re_properties"),{...form,photos:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});
      await reload();
      setShowForm(false);
      setForm({name:"",type:"fixed_rental",address:"",bedrooms:1,sqm:0,estimatedValueUSD:0,purchasePriceUSD:0,monthlyIncomeARS:0,monthlyExpensesARS:0,status:"rented",description:""});
      setPage("dashboard");
    } catch(e){setError("Error al guardar. Verificá las reglas de Firestore: " + e.message);}
    finally{setSaving(false);}
  }

  async function saveEdit(id) {
    try {
      await updateDoc(doc(db,"re_properties",id),{...editValues,updatedAt:new Date().toISOString()});
      await reload();
      setEditingId(null);
    } catch(e){alert("Error al guardar: "+e.message);}
  }

  async function remove(id){
    if(!confirm("¿Eliminar esta propiedad?"))return;
    await deleteDoc(doc(db,"re_properties",id));
    await reload();
  }

  function startEdit(p) {
    setEditingId(p.id);
    setEditValues({
      estimatedValueUSD: p.estimatedValueUSD,
      monthlyIncomeARS:  p.monthlyIncomeARS || 0,
      monthlyExpensesARS: p.monthlyExpensesARS || 0,
      status: p.status,
    });
  }

  const statusMap={
    rented:      {label:"Alquilado",     color:C.green,   bg:C.greenLight},
    available:   {label:"Disponible",    color:C.blueMid, bg:C.blueLight},
    maintenance: {label:"Mantenimiento", color:C.yellow,  bg:C.yellowLight},
  };

  return (
    <div style={{animation:"fadeIn 0.25s ease"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:32}}>
        <div>
          <h1 style={{fontSize:26,fontWeight:800,letterSpacing:"-0.5px"}}>Propiedades</h1>
          <p style={{color:C.textSec,fontSize:14,marginTop:5}}>{properties.length} inmuebles en el portfolio</p>
        </div>
        <button onClick={()=>setShowForm(true)} style={S.btn}>+ Nueva propiedad</button>
      </div>

      {properties.length===0?(
        <div style={{...S.card,textAlign:"center",padding:60}}>
          <div style={{fontSize:48,marginBottom:16}}>🏠</div>
          <div style={{fontSize:18,fontWeight:700,marginBottom:8}}>No hay propiedades</div>
          <div style={{color:C.textSec,marginBottom:24}}>Agregá tu primer inmueble</div>
          <button onClick={()=>setShowForm(true)} style={S.btn}>+ Agregar propiedad</button>
        </div>
      ):(
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:18}}>
          {properties.map(p=>{
            const st=statusMap[p.status]||{label:p.status,color:C.textSec,bg:C.bg};
            const isEditing=editingId===p.id;

            // Usar ingresos/egresos cargados en la propiedad, o de transacciones
            const propTxs=transactions.filter(t=>t.propertyId===p.id);
            const txInc=propTxs.filter(t=>t.type==="income").reduce((s,t)=>s+t.amountUSD,0)/3;
            const txExp=propTxs.filter(t=>t.type==="expense").reduce((s,t)=>s+t.amountUSD,0)/3;

            const monthIncARS = p.monthlyIncomeARS || 0;
            const monthExpARS = p.type==="fixed_rental" ? 0 : (p.monthlyExpensesARS || 0);
            const monthIncUSD = monthIncARS > 0 ? arsToUsd(monthIncARS, tc) : txInc;
            const monthExpUSD = monthExpARS > 0 ? arsToUsd(monthExpARS, tc) : txExp;
            const monthNetUSD = monthIncUSD - monthExpUSD;

            const cap = p.estimatedValueUSD>0&&monthNetUSD>0 ? (monthNetUSD*12/p.estimatedValueUSD)*100 : 0;
            const payback = monthNetUSD>0 ? p.estimatedValueUSD/(monthNetUSD*12) : null;
            const plusvalia = p.estimatedValueUSD - p.purchasePriceUSD;

            return (
              <div key={p.id} style={{...S.card,borderTop:"3px solid "+st.color}}>
                <div style={{display:"flex",justifyContent:"space-between",marginBottom:16}}>
                  <div>
                    <div style={{fontSize:16,fontWeight:700,marginBottom:3}}>{p.name}</div>
                    <div style={{fontSize:12,color:C.textSec}}>{p.address||"Sin dirección"}</div>
                  </div>
                  <div style={{display:"flex",gap:8,alignItems:"flex-start"}}>
                    {!isEditing&&<span style={{fontSize:11,background:st.bg,color:st.color,padding:"3px 10px",borderRadius:20,fontWeight:600}}>{st.label}</span>}
                    <button onClick={()=>isEditing?saveEdit(p.id):startEdit(p)} style={{background:isEditing?C.greenLight:C.blueLight,border:"none",color:isEditing?C.green:C.blueMid,borderRadius:8,padding:"4px 10px",cursor:"pointer",fontSize:12,fontWeight:600}}>
                      {isEditing?"✓ Guardar":"✏ Editar"}
                    </button>
                    {isEditing&&<button onClick={()=>setEditingId(null)} style={{background:C.bg,border:"1px solid "+C.border,borderRadius:8,padding:"4px 8px",cursor:"pointer",fontSize:12,color:C.textSec}}>Cancelar</button>}
                    {!isEditing&&<button onClick={()=>remove(p.id)} style={{background:C.redLight,border:"none",color:C.red,borderRadius:8,width:28,height:28,cursor:"pointer",fontSize:16,display:"flex",alignItems:"center",justifyContent:"center"}}>×</button>}
                  </div>
                </div>

                {/* Valores editables */}
                {isEditing?(
                  <div style={{background:C.bg,borderRadius:12,padding:14,marginBottom:14,border:"1px solid "+C.border}}>
                    <div style={{fontSize:12,fontWeight:600,color:C.textSec,marginBottom:12}}>Editando valores</div>
                    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                      {[
                        {label:"Valor estimado (USD)", field:"estimatedValueUSD", prefix:"USD"},
                        {label:"Ingreso mensual (ARS)", field:"monthlyIncomeARS", prefix:"$"},
                        {label:"Egresos mensuales (ARS)", field:"monthlyExpensesARS", prefix:"$", hide:p.type==="fixed_rental"},
                      ].filter(x=>!x.hide).map(({label,field,prefix})=>(
                        <div key={field}>
                          <div style={{fontSize:10,color:C.textMuted,textTransform:"uppercase",letterSpacing:"0.4px",marginBottom:4,fontWeight:500}}>{label}</div>
                          <div style={{position:"relative"}}>
                            <span style={{position:"absolute",left:10,top:"50%",transform:"translateY(-50%)",color:C.textMuted,fontSize:12}}>{prefix}</span>
                            <input type="number" value={editValues[field]||0} onChange={e=>setEditValues(v=>({...v,[field]:Number(e.target.value)}))}
                              style={{...S.input,paddingLeft:prefix==="USD"?36:22,fontSize:14,fontWeight:600}}/>
                          </div>
                        </div>
                      ))}
                      <div>
                        <div style={{fontSize:10,color:C.textMuted,textTransform:"uppercase",letterSpacing:"0.4px",marginBottom:4,fontWeight:500}}>Estado</div>
                        <select value={editValues.status} onChange={e=>setEditValues(v=>({...v,status:e.target.value}))} style={S.input}>
                          <option value="rented">Alquilado</option>
                          <option value="available">Disponible</option>
                          <option value="maintenance">Mantenimiento</option>
                        </select>
                      </div>
                    </div>
                  </div>
                ):(
                  <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:8,marginBottom:10}}>
                    {[
                      {label:"Tipo",  value:p.type==="fixed_rental"?"Renta fija":"Temporal"},
                      {label:"Valor", value:fUSD(p.estimatedValueUSD)},
                      {label:"Dorms", value:p.bedrooms||"—"},
                      {label:"Sup.",  value:p.sqm?p.sqm+"m²":"—"},
                    ].map(({label,value})=>(
                      <div key={label} style={{background:C.bg,borderRadius:8,padding:"8px 10px"}}>
                        <div style={{fontSize:9,color:C.textMuted,textTransform:"uppercase",letterSpacing:"0.4px",marginBottom:2,fontWeight:500}}>{label}</div>
                        <div style={{fontSize:12,fontWeight:600}}>{value}</div>
                      </div>
                    ))}
                  </div>
                )}

                {/* Métricas financieras */}
                <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8,marginBottom:10}}>
                  {[
                    {label:"Ingreso bruto/mes", value:monthIncUSD>0?fUSD(monthIncUSD):"—", sub:monthIncARS>0?fARS(monthIncARS):null},
                    {label:"Ingreso neto/mes",  value:monthNetUSD>0?fUSD(monthNetUSD):"—", color:monthNetUSD>0?C.green:C.textMuted},
                  ].map(({label,value,sub,color})=>(
                    <div key={label} style={{background:C.bg,borderRadius:8,padding:"10px 12px"}}>
                      <div style={{fontSize:9,color:C.textMuted,textTransform:"uppercase",letterSpacing:"0.4px",marginBottom:2,fontWeight:500}}>{label}</div>
                      <div style={{fontSize:14,fontWeight:700,color:color||C.text}}>{value}</div>
                      {sub&&<div style={{fontSize:10,color:C.textMuted,marginTop:1}}>{sub}</div>}
                    </div>
                  ))}
                </div>

                <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:10}}>
                  {[
                    {label:"Cap Rate",  value:cap>0?fPct(cap):"—",         color:cap>4?C.green:cap>0?C.yellow:C.textMuted},
                    {label:"Payback",   value:payback?payback.toFixed(1)+" años":"—", color:payback&&payback<20?C.green:C.yellow},
                    {label:"Plusvalía", value:fUSD(plusvalia),              color:plusvalia>0?C.green:C.red},
                  ].map(({label,value,color})=>(
                    <div key={label} style={{background:C.bg,borderRadius:8,padding:"8px 10px"}}>
                      <div style={{fontSize:9,color:C.textMuted,textTransform:"uppercase",letterSpacing:"0.4px",marginBottom:2,fontWeight:500}}>{label}</div>
                      <div style={{fontSize:13,fontWeight:700,color}}>{value}</div>
                    </div>
                  ))}
                </div>

                {monthNetUSD>0&&payback&&(
                  <div style={{background:payback<20?C.greenLight:C.yellowLight,borderRadius:10,padding:"10px 14px",display:"flex",justifyContent:"space-between"}}>
                    <span style={{fontSize:13,color:payback<20?C.green:C.yellow,fontWeight:500}}>Recupero de inversión</span>
                    <span style={{fontSize:14,fontWeight:800,color:payback<20?C.green:C.yellow}}>{payback.toFixed(1)} años</span>
                  </div>
                )}

                {p.description&&<div style={{marginTop:12,fontSize:12,color:C.textSec,paddingTop:12,borderTop:"1px solid "+C.border}}>{p.description}</div>}
              </div>
            );
          })}
        </div>
      )}

      {showForm&&(
        <div style={S.modal}>
          <div style={S.modalBox}>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:24}}>
              <div style={{fontSize:18,fontWeight:700}}>Nueva propiedad</div>
              <button onClick={()=>setShowForm(false)} style={{background:"none",border:"none",color:C.textSec,fontSize:22,cursor:"pointer"}}>×</button>
            </div>
            {error&&<div style={{background:C.redLight,border:"1px solid #fca5a5",borderRadius:10,padding:"12px 14px",fontSize:13,color:C.red,marginBottom:16,fontWeight:500}}>{error}</div>}
            <div style={{display:"flex",flexDirection:"column",gap:14}}>
              <div><label style={S.label}>Nombre *</label><input style={S.input} placeholder="Depto 1 · Palermo" value={form.name} onChange={e=>setF("name",e.target.value)}/></div>
              <div><label style={S.label}>Dirección</label><input style={S.input} placeholder="Av. Santa Fe 1234, CABA" value={form.address} onChange={e=>setF("address",e.target.value)}/></div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                <div><label style={S.label}>Tipo</label><select style={S.input} value={form.type} onChange={e=>setF("type",e.target.value)}><option value="fixed_rental">Renta fija</option><option value="short_term">Renta temporal</option></select></div>
                <div><label style={S.label}>Estado</label><select style={S.input} value={form.status} onChange={e=>setF("status",e.target.value)}><option value="rented">Alquilado</option><option value="available">Disponible</option><option value="maintenance">Mantenimiento</option></select></div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                <div><label style={S.label}>Valor estimado (USD)</label><input type="number" style={S.input} placeholder="67000" value={form.estimatedValueUSD||""} onChange={e=>setF("estimatedValueUSD",Number(e.target.value))}/></div>
                <div><label style={S.label}>Precio de compra (USD)</label><input type="number" style={S.input} placeholder="67000" value={form.purchasePriceUSD||""} onChange={e=>setF("purchasePriceUSD",Number(e.target.value))}/></div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                <div><label style={S.label}>Ingreso mensual (ARS)</label><input type="number" style={S.input} placeholder="476670" value={form.monthlyIncomeARS||""} onChange={e=>setF("monthlyIncomeARS",Number(e.target.value))}/></div>
                <div><label style={S.label}>{form.type==="fixed_rental"?"Egresos (0 por ahora)":"Egresos mensuales (ARS)"}</label><input type="number" style={S.input} placeholder="0" value={form.monthlyExpensesARS||""} onChange={e=>setF("monthlyExpensesARS",Number(e.target.value))} disabled={form.type==="fixed_rental"}/></div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                <div><label style={S.label}>Dormitorios</label><input type="number" style={S.input} min={0} value={form.bedrooms} onChange={e=>setF("bedrooms",Number(e.target.value))}/></div>
                <div><label style={S.label}>Superficie (m²)</label><input type="number" style={S.input} min={0} value={form.sqm||""} onChange={e=>setF("sqm",Number(e.target.value))}/></div>
              </div>
              <div><label style={S.label}>Descripción</label><textarea style={{...S.input,minHeight:60,resize:"none"}} value={form.description} onChange={e=>setF("description",e.target.value)}/></div>
              <div style={{display:"flex",gap:10}}>
                <button onClick={save} disabled={saving} style={{...S.btnGreen,flex:1,justifyContent:"center"}}>{saving?"Guardando...":"Guardar propiedad"}</button>
                <button onClick={()=>setShowForm(false)} style={S.btnSec}>Cancelar</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ── RESERVAS ──────────────────────────────────────────────────────────────────
function Bookings({ properties, bookings, tc, reload, db, setPage }) {
  const [showForm,setShowForm]=useState(false);
  const [year,setYear]=useState(new Date().getFullYear());
  const [month,setMonth]=useState(new Date().getMonth());
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState("");
  const shortProps=properties.filter(p=>p.type==="short_term"||p.type==="short-term"||p.type==="temporal");
  const [propId,setPropId]=useState(shortProps[0]?.id||"");
  const [commPct,setCommPct]=useState(0);
  const [form,setForm]=useState({guestName:"",guestEmail:"",guestPhone:"",checkIn:"",checkOut:"",source:"direct",status:"confirmed",notes:""});

  useEffect(()=>{ if(shortProps.length>0&&!propId) setPropId(shortProps[0].id); },[shortProps.length]);
  function setF(f,v){setForm(p=>({...p,[f]:v}));}

  const daysInMonth=new Date(year,month+1,0).getDate();
  const firstDay=new Date(year,month,1).getDay();
  const todayD=new Date();

  const occupiedMap=useMemo(()=>{
    const m={};
    bookings.filter(b=>b.propertyId===propId&&b.status!=="cancelled").forEach(b=>{
      const cur=new Date(b.checkIn),end=new Date(b.checkOut);
      while(cur<end){m[cur.toISOString().split("T")[0]]=b;cur.setDate(cur.getDate()+1);}
    });
    return m;
  },[bookings,propId]);

  const nights=form.checkIn&&form.checkOut?Math.max(0,Math.round((new Date(form.checkOut)-new Date(form.checkIn))/86400000)):0;
  const pricing=nights>0?calcPricing(nights,70000,15000,commPct):null;

  const PLATAFORMAS=[
    {key:"direct",  label:"Directa",  pct:0},
    {key:"airbnb",  label:"Airbnb",   pct:15},
    {key:"booking", label:"Booking",  pct:15},
    {key:"other",   label:"Otra",     pct:10},
  ];

  function handleSourceChange(source){
    setF("source",source);
    setCommPct(PLATAFORMAS.find(p=>p.key===source)?.pct||0);
  }

  async function save(){
    if(!propId){setError("No hay propiedades de renta temporal seleccionadas.");return;}
    if(!form.guestName){setError("Ingresá el nombre del huésped.");return;}
    if(!form.checkIn||!form.checkOut){setError("Ingresá las fechas de check-in y check-out.");return;}
    if(nights<=0){setError("Las fechas no son válidas. Check-out debe ser posterior al check-in.");return;}
    setSaving(true);setError("");
    try {
      await addDoc(collection(db,"re_bookings"),{
        ...form,propertyId:propId,nights,
        basePricePerNight:70000,cleaningFee:15000,commissionPct:commPct,
        totalARS:pricing?.total||0,
        totalNetoARS:pricing?.neto||0,
        comisionARS:pricing?.comision||0,
        totalUSD:pricing?arsToUsd(pricing.neto,tc):0,
        exchangeRateUsed:tc,
        createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),
      });
      await reload();
      setShowForm(false);
      setForm({guestName:"",guestEmail:"",guestPhone:"",checkIn:"",checkOut:"",source:"direct",status:"confirmed",notes:""});
      setCommPct(0);
    } catch(e){setError("Error al guardar: " + e.message);}
    finally{setSaving(false);}
  }

  async function deleteBooking(id, guestName) {
    if (!confirm(`¿Eliminar la reserva de ${guestName}? Esta acción no se puede deshacer.`)) return;
    try {
      // Move to movimientos before deleting
      const bk = bookings.find(b => b.id === id);
      if (bk) {
        await addDoc(collection(db, "re_movimientos"), {
          ...bk,
          tipo: "reserva_eliminada",
          eliminadaEn: new Date().toISOString(),
        });
      }
      await deleteDoc(doc(db, "re_bookings", id));
      await reload();
    } catch(e) { alert("Error al eliminar: " + e.message); }
  }

  const monthIncome=bookings.filter(b=>b.propertyId===propId&&b.status!=="cancelled"&&new Date(b.checkIn).getMonth()===month).reduce((s,b)=>s+(b.totalNetoARS||b.totalARS||0),0);
  const occupiedNights=Object.values(occupiedMap).filter(b=>b.status!=="blocked"&&new Date(b.checkIn).getMonth()===month).length;

  return (
    <div style={{animation:"fadeIn 0.25s ease"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:32}}>
        <div>
          <h1 style={{fontSize:26,fontWeight:800,letterSpacing:"-0.5px"}}>Reservas</h1>
          <p style={{color:C.textSec,fontSize:14,marginTop:5}}>Calendario · Renta temporal</p>
        </div>
        <div style={{display:"flex",gap:10}}>
          {shortProps.length>1&&<select style={{...S.input,width:200}} value={propId} onChange={e=>setPropId(e.target.value)}>{shortProps.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select>}
          <button onClick={()=>setShowForm(true)} style={S.btn}>+ Nueva reserva</button>
        </div>
      </div>

      {shortProps.length===0?(
        <div style={{...S.card,textAlign:"center",padding:60,color:C.textMuted}}><div style={{fontSize:40,marginBottom:12}}>📅</div><div>No tenés propiedades de renta temporal</div></div>
      ):(
        <>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:14,marginBottom:24}}>
            {[
              {label:"Ingresos netos del mes",value:fARS(monthIncome),sub:fUSD(monthIncome/tc),color:C.green},
              {label:"Noches ocupadas",value:String(occupiedNights),sub:Math.round(occupiedNights/daysInMonth*100)+"% del mes"},
              {label:"Reservas activas",value:String(bookings.filter(b=>b.status==="confirmed").length),sub:"confirmadas"},
            ].map(({label,value,sub,color})=>(
              <div key={label} style={S.card}>
                <div style={{fontSize:11,color:C.textMuted,fontWeight:600,letterSpacing:"0.4px",textTransform:"uppercase",marginBottom:8}}>{label}</div>
                <div style={{fontSize:22,fontWeight:800,color:color||C.text}}>{value}</div>
                <div style={{fontSize:12,color:C.textMuted,marginTop:3}}>{sub}</div>
              </div>
            ))}
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:18}}>
            <div style={S.card}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
                <button onClick={()=>{if(month===0){setMonth(11);setYear(y=>y-1);}else setMonth(m=>m-1);}} style={{...S.btnSec,padding:"7px 14px"}}>‹</button>
                <div style={{fontSize:15,fontWeight:700}}>{MONTHS_FULL[month]} {year}</div>
                <button onClick={()=>{if(month===11){setMonth(0);setYear(y=>y+1);}else setMonth(m=>m+1);}} style={{...S.btnSec,padding:"7px 14px"}}>›</button>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:2,marginBottom:6}}>
                {DAYS.map(d=><div key={d} style={{textAlign:"center",fontSize:11,color:C.textMuted,padding:"4px 0",fontWeight:600}}>{d}</div>)}
              </div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:2}}>
                {Array.from({length:firstDay}).map((_,i)=><div key={`e${i}`}/>)}
                {Array.from({length:daysInMonth}).map((_,i)=>{
                  const d=i+1;
                  const ds=`${year}-${String(month+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`;
                  const bk=occupiedMap[ds];
                  const isToday=todayD.getFullYear()===year&&todayD.getMonth()===month&&todayD.getDate()===d;
                  return <div key={d} title={bk?bk.guestName:""} style={{aspectRatio:"1",display:"flex",alignItems:"center",justifyContent:"center",borderRadius:8,fontSize:12,fontWeight:bk?700:400,background:bk?.status==="blocked"?C.redLight:bk?C.yellowLight:"transparent",color:bk?.status==="blocked"?C.red:bk?C.yellow:C.textSec,outline:isToday?"2px solid "+C.green:"none",outlineOffset:1}}>{d}</div>;
                })}
              </div>
              <div style={{display:"flex",gap:14,marginTop:14,paddingTop:14,borderTop:"1px solid "+C.border}}>
                {[{bg:C.yellowLight,color:C.yellow,label:"Ocupado"},{bg:C.redLight,color:C.red,label:"Bloqueado"}].map(({bg,color,label})=>(
                  <div key={label} style={{display:"flex",alignItems:"center",gap:6}}><div style={{width:10,height:10,borderRadius:3,background:bg,border:"1px solid "+color}}/><span style={{fontSize:11,color:C.textSec}}>{label}</span></div>
                ))}
              </div>
            </div>
            <div style={S.card}>
              <div style={{fontSize:15,fontWeight:700,marginBottom:16}}>Próximas reservas</div>
              {bookings.filter(b=>b.status==="confirmed").length===0?(
                <div style={{textAlign:"center",padding:"40px 0",color:C.textMuted}}><div style={{fontSize:32,marginBottom:12}}>📭</div><div>No hay reservas</div></div>
              ):(
                <div style={{display:"flex",flexDirection:"column",gap:10}}>
                  {bookings.filter(b=>b.status==="confirmed").sort((a,b)=>a.checkIn.localeCompare(b.checkIn)).map(b=>(
                    <div key={b.id} style={{background:C.bg,borderRadius:12,padding:"12px 14px",border:"1px solid "+C.border}}>
                      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:5}}>
                        <div style={{flex:1}}>
                          <div style={{fontSize:14,fontWeight:600}}>{b.guestName}</div>
                          <div style={{fontSize:12,color:C.textSec,marginTop:2}}>{b.checkIn} → {b.checkOut} · {b.nights} noches</div>
                          {b.source&&<div style={{fontSize:11,color:C.textMuted,marginTop:2,textTransform:"capitalize"}}>Fuente: {b.source}{b.commissionPct>0?` (${b.commissionPct}%)`:""}</div>}
                        </div>
                        <div style={{textAlign:"right",marginLeft:10}}>
                          <div style={{fontSize:14,fontWeight:700,color:C.green}}>{fARS(b.totalNetoARS||b.totalARS)}</div>
                          {b.comisionARS>0&&<div style={{fontSize:10,color:C.red}}>−{fARS(b.comisionARS)} com.</div>}
                          <button onClick={()=>deleteBooking(b.id,b.guestName)} style={{marginTop:6,background:C.redLight,border:"none",color:C.red,borderRadius:6,padding:"3px 8px",fontSize:11,cursor:"pointer",fontWeight:600}}>
                            🗑 Eliminar
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </>
      )}

      {showForm&&(
        <div style={S.modal}>
          <div style={S.modalBox}>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:24}}>
              <div style={{fontSize:18,fontWeight:700}}>Nueva reserva</div>
              <button onClick={()=>setShowForm(false)} style={{background:"none",border:"none",color:C.textSec,fontSize:22,cursor:"pointer"}}>×</button>
            </div>
            {error&&<div style={{background:C.redLight,border:"1px solid #fca5a5",borderRadius:10,padding:"12px 14px",fontSize:13,color:C.red,marginBottom:16,fontWeight:500}}>{error}</div>}
            <div style={{display:"flex",flexDirection:"column",gap:14}}>
              <div><label style={S.label}>Huésped *</label><input style={S.input} value={form.guestName} onChange={e=>setF("guestName",e.target.value)} placeholder="Juan Pérez"/></div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                <div><label style={S.label}>Email</label><input type="email" style={S.input} value={form.guestEmail} onChange={e=>setF("guestEmail",e.target.value)}/></div>
                <div><label style={S.label}>Teléfono</label><input style={S.input} value={form.guestPhone} onChange={e=>setF("guestPhone",e.target.value)}/></div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
                <div><label style={S.label}>Check-in *</label><input type="date" style={S.input} value={form.checkIn} onChange={e=>setF("checkIn",e.target.value)}/></div>
                <div><label style={S.label}>Check-out *</label><input type="date" style={S.input} value={form.checkOut} onChange={e=>setF("checkOut",e.target.value)}/></div>
              </div>
              <div>
                <label style={S.label}>Plataforma / Fuente</label>
                <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:8}}>
                  {PLATAFORMAS.map(({key,label,pct})=>(
                    <button key={key} onClick={()=>handleSourceChange(key)} style={{padding:"8px 6px",borderRadius:8,border:"1.5px solid "+(form.source===key?C.blue:C.border),background:form.source===key?C.blueLight:C.white,color:form.source===key?C.blue:C.textSec,fontSize:12,fontWeight:form.source===key?700:400,cursor:"pointer"}}>
                      {label}{pct>0&&<div style={{fontSize:10,color:C.red}}>{pct}%</div>}
                    </button>
                  ))}
                </div>
              </div>
              <div><label style={S.label}>Estado</label><select style={S.input} value={form.status} onChange={e=>setF("status",e.target.value)}><option value="confirmed">Confirmada</option><option value="blocked">Bloqueado</option></select></div>
              {pricing&&(
                <div style={{background:C.greenLight,borderRadius:12,padding:"14px 16px"}}>
                  <div style={{fontSize:13,fontWeight:600,color:C.green,marginBottom:6}}>{nights} noches · {pricing.label}</div>
                  <div style={{display:"flex",justifyContent:"space-between"}}>
                    <div><div style={{fontSize:11,color:C.textSec}}>Total bruto</div><div style={{fontSize:16,fontWeight:700}}>{fARS(pricing.total)}</div></div>
                    {pricing.comision>0&&<div><div style={{fontSize:11,color:C.red}}>Comisión ({commPct}%)</div><div style={{fontSize:16,fontWeight:700,color:C.red}}>−{fARS(pricing.comision)}</div></div>}
                    <div><div style={{fontSize:11,color:C.green}}>Neto</div><div style={{fontSize:18,fontWeight:800,color:C.green}}>{fARS(pricing.neto)}</div></div>
                  </div>
                  <div style={{fontSize:11,color:C.textSec,marginTop:6}}>{fARS(pricing.perNight)}/noche + $15.000 limpieza · {fUSD(arsToUsd(pricing.neto,tc))} USD</div>
                </div>
              )}
              <div style={{display:"flex",gap:10}}>
                <button onClick={save} disabled={saving} style={{...S.btnGreen,flex:1,justifyContent:"center"}}>{saving?"Guardando...":"Guardar reserva"}</button>
                <button onClick={()=>setShowForm(false)} style={S.btnSec}>Cancelar</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ── TRANSACCIONES ─────────────────────────────────────────────────────────────
function Transactions({ properties, transactions, tc, reload, db }) {
  const [showForm,setShowForm]=useState(false);
  const [filter,setFilter]=useState("all");
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState("");
  const [type,setType]=useState("income");
  const [amountARS,setAmountARS]=useState("");
  const [form,setForm]=useState({propertyId:"",category:"rent",date:todayStr(),description:""});
  function setF(f,v){setForm(p=>({...p,[f]:v}));}

  const CATS={
    income:[["rent","Alquiler"],["booking","Reserva"]],
    expense:[["expensas","Expensas"],["expensas_extraordinarias","Expensas ext."],["impuesto","Impuesto"],["reparacion","Reparación"],["comision","Comisión plataforma"],["limpieza","Limpieza"],["seguro","Seguro"],["internet","Internet"],["luz","Luz/Gas"],["otros","Otros"]],
  };
  const catLabel={rent:"Alquiler",booking:"Reserva",expensas:"Expensas",expensas_extraordinarias:"Expensas ext.",impuesto:"Impuesto",reparacion:"Reparación",comision:"Comisión",limpieza:"Limpieza",seguro:"Seguro",internet:"Internet",luz:"Luz/Gas",otros:"Otros"};

  const totals={
    income: transactions.filter(t=>t.type==="income").reduce((s,t)=>s+t.amountUSD,0),
    expense:transactions.filter(t=>t.type==="expense").reduce((s,t)=>s+t.amountUSD,0),
  };

  async function save(){
    if(!form.propertyId||!amountARS||!form.description){setError("Completá todos los campos.");return;}
    setSaving(true);setError("");
    try {
      const ars=Number(amountARS);
      await addDoc(collection(db,"re_transactions"),{...form,type,amountARS:ars,amountUSD:arsToUsd(ars,tc),exchangeRateUsed:tc,createdAt:new Date().toISOString()});
      await reload();
      setShowForm(false);setAmountARS("");
      setForm({propertyId:"",category:"rent",date:todayStr(),description:""});
    } catch(e){setError("Error al guardar: " + e.message);}
    finally{setSaving(false);}
  }

  const filtered=filter==="all"?transactions:transactions.filter(t=>t.type===filter);
  const propName=id=>properties.find(p=>p.id===id)?.name||"—";

  return (
    <div style={{animation:"fadeIn 0.25s ease"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:32}}>
        <div>
          <h1 style={{fontSize:26,fontWeight:800,letterSpacing:"-0.5px"}}>Transacciones</h1>
          <p style={{color:C.textSec,fontSize:14,marginTop:5}}>{transactions.length} registros</p>
        </div>
        <button onClick={()=>setShowForm(true)} style={S.btn}>+ Nueva transacción</button>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:14,marginBottom:24}}>
        {[
          {label:"Ingresos totales",value:fUSD(totals.income), color:C.green,icon:"↑"},
          {label:"Egresos totales", value:fUSD(totals.expense),color:C.red,  icon:"↓"},
          {label:"Resultado neto",  value:fUSD(totals.income-totals.expense),color:totals.income>=totals.expense?C.green:C.red,icon:"="},
        ].map(({label,value,color,icon})=>(
          <div key={label} style={{...S.card,display:"flex",alignItems:"center",gap:16}}>
            <div style={{width:44,height:44,borderRadius:12,background:color+"22",display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,color}}>{icon}</div>
            <div>
              <div style={{fontSize:11,color:C.textMuted,textTransform:"uppercase",letterSpacing:"0.4px",marginBottom:4,fontWeight:600}}>{label}</div>
              <div style={{fontSize:22,fontWeight:800,color}}>{value}</div>
            </div>
          </div>
        ))}
      </div>

      <div style={{display:"flex",gap:8,marginBottom:18}}>
        {["all","income","expense"].map(f=>(
          <button key={f} onClick={()=>setFilter(f)} style={{padding:"8px 16px",borderRadius:8,border:"1.5px solid "+(filter===f?C.blue:C.border),background:filter===f?C.blue:C.white,color:filter===f?"#fff":C.textSec,fontSize:13,fontWeight:500,cursor:"pointer"}}>
            {{all:"Todos",income:"Ingresos",expense:"Egresos"}[f]}
          </button>
        ))}
      </div>

      <div style={{...S.card,padding:0,overflow:"hidden"}}>
        {filtered.length===0?(
          <div style={{textAlign:"center",padding:60,color:C.textMuted}}><div style={{fontSize:36,marginBottom:12}}>💳</div><div>No hay transacciones</div></div>
        ):(
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
            <thead>
              <tr style={{borderBottom:"1px solid "+C.border,background:C.bg}}>
                {["Fecha","Propiedad","Descripción","Categoría","ARS","USD"].map(h=>(
                  <th key={h} style={{padding:"12px 18px",textAlign:"left",fontSize:11,color:C.textMuted,fontWeight:600,letterSpacing:"0.4px",textTransform:"uppercase"}}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map(t=>(
                <tr key={t.id} style={{borderBottom:"1px solid "+C.border}}>
                  <td style={{padding:"11px 18px",color:C.textSec}}>{t.date}</td>
                  <td style={{padding:"11px 18px",color:C.textSec,fontSize:12}}>{propName(t.propertyId)}</td>
                  <td style={{padding:"11px 18px",fontWeight:500}}>{t.description}</td>
                  <td style={{padding:"11px 18px"}}><span style={{background:C.bg,color:C.textSec,padding:"3px 8px",borderRadius:6,fontSize:11,border:"1px solid "+C.border}}>{catLabel[t.category]||t.category}</span></td>
                  <td style={{padding:"11px 18px",color:C.textSec}}>{fARS(t.amountARS)}</td>
                  <td style={{padding:"11px 18px",fontWeight:700,color:t.type==="income"?C.green:C.red}}>{t.type==="income"?"+":"−"}{fUSD(t.amountUSD)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {showForm&&(
        <div style={S.modal}>
          <div style={S.modalBox}>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:24}}>
              <div style={{fontSize:18,fontWeight:700}}>Nueva transacción</div>
              <button onClick={()=>setShowForm(false)} style={{background:"none",border:"none",color:C.textSec,fontSize:22,cursor:"pointer"}}>×</button>
            </div>
            {error&&<div style={{background:C.redLight,border:"1px solid #fca5a5",borderRadius:10,padding:"12px 14px",fontSize:13,color:C.red,marginBottom:16,fontWeight:500}}>{error}</div>}
            <div style={{display:"flex",flexDirection:"column",gap:14}}>
              <div style={{display:"flex",gap:8}}>
                {["income","expense"].map(t=>(
                  <button key={t} onClick={()=>{setType(t);setF("category",t==="income"?"rent":"expensas");}} style={{flex:1,padding:"11px 0",borderRadius:10,border:"1.5px solid "+(type===t?(t==="income"?C.green:C.red):C.border),background:type===t?(t==="income"?C.greenLight:C.redLight):C.white,color:type===t?(t==="income"?C.green:C.red):C.textSec,fontWeight:600,fontSize:14,cursor:"pointer"}}>
                    {t==="income"?"↑ Ingreso":"↓ Egreso"}
                  </button>
                ))}
              </div>
              <div><label style={S.label}>Propiedad *</label><select style={S.input} value={form.propertyId} onChange={e=>setF("propertyId",e.target.value)}><option value="">Seleccioná una propiedad</option>{properties.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></div>
              <div><label style={S.label}>Categoría</label><select style={S.input} value={form.category} onChange={e=>setF("category",e.target.value)}>{CATS[type].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></div>
              <div><label style={S.label}>Descripción *</label><input style={S.input} placeholder="Alquiler mayo 2025" value={form.description} onChange={e=>setF("description",e.target.value)}/></div>
              <div><label style={S.label}>Fecha</label><input type="date" style={S.input} value={form.date} onChange={e=>setF("date",e.target.value)}/></div>
              <div>
                <label style={S.label}>Monto en ARS *</label>
                <input type="number" style={S.input} placeholder="476670" value={amountARS} onChange={e=>setAmountARS(e.target.value)}/>
                {amountARS>0&&<div style={{fontSize:12,color:C.textSec,marginTop:6}}>≈ <span style={{color:C.green,fontWeight:600}}>{fUSD(arsToUsd(Number(amountARS),tc))}</span> al tipo ${tc.toLocaleString("es-AR")}</div>}
              </div>
              <div style={{display:"flex",gap:10}}>
                <button onClick={save} disabled={saving} style={{...S.btnGreen,flex:1,justifyContent:"center"}}>{saving?"Guardando...":"Guardar"}</button>
                <button onClick={()=>setShowForm(false)} style={S.btnSec}>Cancelar</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ── MOVIMIENTOS ──────────────────────────────────────────────────────────────
function Movimientos({ db }) {
  const [movimientos, setMovimientos] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getDocs(collection(db, "re_movimientos"))
      .then(snap => {
        setMovimientos(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      })
      .catch(e => console.error(e))
      .finally(() => setLoading(false));
  }, []);

  async function deleteMovimiento(id) {
    if (!confirm("¿Eliminar este registro del historial?")) return;
    await deleteDoc(doc(db, "re_movimientos", id));
    setMovimientos(m => m.filter(x => x.id !== id));
  }

  return (
    <div style={{ animation:"fadeIn 0.25s ease" }}>
      <div style={{ marginBottom:32 }}>
        <h1 style={{ fontSize:26, fontWeight:800, letterSpacing:"-0.5px" }}>Movimientos</h1>
        <p style={{ color:C.textSec, fontSize:14, marginTop:5 }}>Historial de reservas eliminadas</p>
      </div>

      {loading ? (
        <div style={{ textAlign:"center", padding:60, color:C.textMuted }}>Cargando...</div>
      ) : movimientos.length === 0 ? (
        <div style={{ ...S.card, textAlign:"center", padding:60 }}>
          <div style={{ fontSize:48, marginBottom:16 }}>🗂</div>
          <div style={{ fontSize:16, fontWeight:600, marginBottom:8 }}>Sin movimientos</div>
          <div style={{ color:C.textSec }}>Las reservas eliminadas aparecerán acá</div>
        </div>
      ) : (
        <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
          {movimientos.map(m => (
            <div key={m.id} style={{ ...S.card, display:"flex", alignItems:"center", gap:16 }}>
              <div style={{ width:44, height:44, borderRadius:12, background:C.redLight, display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>🗑</div>
              <div style={{ flex:1 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                  <span style={{ fontSize:14, fontWeight:700 }}>{m.guestName}</span>
                  <span style={{ fontSize:11, background:C.redLight, color:C.red, padding:"2px 8px", borderRadius:20, fontWeight:600 }}>Reserva eliminada</span>
                </div>
                <div style={{ fontSize:12, color:C.textSec }}>{m.checkIn} → {m.checkOut} · {m.nights} noches</div>
                <div style={{ fontSize:12, color:C.textSec, marginTop:2 }}>
                  Total: <span style={{ fontWeight:600 }}>{fARS(m.totalNetoARS || m.totalARS || 0)}</span>
                  {m.source && <span style={{ marginLeft:8, textTransform:"capitalize" }}>· {m.source}</span>}
                </div>
              </div>
              <div style={{ textAlign:"right" }}>
                <div style={{ fontSize:13, fontWeight:700, color:C.red }}>{fUSD(m.totalUSD || 0)}</div>
                <button onClick={() => deleteMovimiento(m.id)}
                  style={{ marginTop:6, background:"none", border:"1px solid "+C.border, color:C.textMuted, borderRadius:6, padding:"3px 8px", fontSize:11, cursor:"pointer" }}>
                  Limpiar
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── ANÁLISIS ──────────────────────────────────────────────────────────────────
function Analytics({ properties, transactions, tc, pinnedValues, pinValue }) {
  const [propId,setPropId]=useState("all");
  const [years,setYears]=useState(pinnedValues?.projYears||20);

  const props=propId==="all"?properties:properties.filter(p=>p.id===propId);
  const txs=propId==="all"?transactions:transactions.filter(t=>t.propertyId===propId);
  const totalVal=props.reduce((s,p)=>s+p.estimatedValueUSD,0);
  const grossInc=txs.filter(t=>t.type==="income").reduce((s,t)=>s+t.amountUSD,0)/3;
  const expenses=txs.filter(t=>t.type==="expense").reduce((s,t)=>s+t.amountUSD,0)/3;
  const netInc=grossInc-expenses, annualNet=netInc*12;
  const grossY=totalVal>0?(grossInc*12/totalVal)*100:0;
  const netY=totalVal>0?(annualNet/totalVal)*100:0;
  const irr=calcIRR(totalVal,annualNet,totalVal,years);

  const projection=Array.from({length:years},(_,i)=>{
    const year=i+1,cum=-totalVal+annualNet*year;
    return {year,cum:Math.round(cum),net:Math.round(annualNet),inc:Math.round(grossInc*12),exp:Math.round(expenses*12),recovered:cum>=0};
  });
  const pbYear=projection.find(r=>r.recovered)?.year;
  const maxAbs=Math.max(...projection.map(r=>Math.abs(r.cum)),1);
  const pricingExamples=[1,2,3,5,7,14].map(n=>({nights:n,...calcPricing(n,70000,15000,0)}));

  return (
    <div style={{animation:"fadeIn 0.25s ease"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:32}}>
        <div>
          <h1 style={{fontSize:26,fontWeight:800,letterSpacing:"-0.5px"}}>Análisis financiero</h1>
          <p style={{color:C.textSec,fontSize:14,marginTop:5}}>TIR · Payback · Cap Rate · Flujo de caja</p>
        </div>
        <div style={{display:"flex",gap:10,alignItems:"center"}}>
          <select style={{...S.input,width:200}} value={propId} onChange={e=>setPropId(e.target.value)}>
            <option value="all">Todo el portfolio</option>
            {properties.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}
          </select>
          <div style={{display:"flex",alignItems:"center",gap:6}}>
            <label style={{fontSize:13,color:C.textSec}}>Años:</label>
            <input type="number" min={5} max={40} value={years} onChange={e=>setYears(Number(e.target.value))} style={{...S.input,width:65,textAlign:"center"}}/>
            <PinBtn pinKey="projYears" value={years} pinnedValues={pinnedValues} pinValue={pinValue}/>
          </div>
        </div>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:14,marginBottom:24}}>
        {[
          {label:"Cap Rate",          value:fPct(netY),  color:netY>4?C.green:C.yellow},
          {label:"TIR",               value:fPct(irr),   color:irr>6?C.green:irr>3?C.yellow:C.red},
          {label:"Rentabilidad neta", value:fPct(netY),  color:C.text},
          {label:"Payback",           value:pbYear?"Año "+pbYear:"N/A", color:pbYear?C.green:C.red},
        ].map(({label,value,color})=>(
          <div key={label} style={S.card}>
            <div style={{fontSize:11,color:C.textMuted,fontWeight:600,letterSpacing:"0.4px",textTransform:"uppercase",marginBottom:10}}>{label}</div>
            <div style={{fontSize:28,fontWeight:800,color,letterSpacing:"-0.5px"}}>{value}</div>
          </div>
        ))}
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:18,marginBottom:18}}>
        <div style={S.card}>
          <div style={{fontSize:15,fontWeight:700,marginBottom:18}}>Flujo mensual (USD)</div>
          {[
            {label:"Ingreso bruto / mes",value:fUSD(grossInc)},
            {label:"Egresos / mes",      value:"− "+fUSD(expenses),color:C.red},
            {label:"Ingreso neto / mes", value:fUSD(netInc),      color:C.green},
            {label:"Ingreso neto / año", value:fUSD(annualNet),    color:C.green,big:true},
          ].map(({label,value,color,big})=>(
            <div key={label} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 0",borderBottom:"1px solid "+C.border}}>
              <span style={{fontSize:13,color:C.textSec}}>{label}</span>
              <span style={{fontSize:big?18:14,fontWeight:big?800:600,color:color||C.text}}>{value}</span>
            </div>
          ))}
        </div>
        <div style={S.card}>
          <div style={{fontSize:15,fontWeight:700,marginBottom:18}}>Rentabilidad</div>
          {[
            {label:"Rentabilidad bruta", value:fPct(grossY)},
            {label:"Rentabilidad neta",  value:fPct(netY)},
            {label:"Cap Rate",           value:fPct(netY)},
            {label:"TIR",                value:fPct(irr),color:irr>6?C.green:C.yellow,big:true},
          ].map(({label,value,color,big})=>(
            <div key={label} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 0",borderBottom:"1px solid "+C.border}}>
              <span style={{fontSize:13,color:C.textSec}}>{label}</span>
              <span style={{fontSize:big?18:14,fontWeight:big?800:600,color:color||C.text}}>{value}</span>
            </div>
          ))}
        </div>
      </div>

      <div style={{...S.card,marginBottom:18}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
          <div>
            <div style={{fontSize:15,fontWeight:700}}>Proyección · {years} años</div>
            <div style={{fontSize:12,color:C.textSec,marginTop:2}}>Acumulado neto en USD</div>
          </div>
          {pbYear&&<span style={{background:C.greenLight,color:C.green,padding:"6px 14px",borderRadius:20,fontSize:13,fontWeight:700}}>Recupero año {pbYear}</span>}
        </div>
        <div style={{display:"flex",alignItems:"flex-end",gap:4,height:130,marginBottom:16}}>
          {projection.map((r,i)=>{
            const pct=Math.abs(r.cum)/maxAbs*100;
            const isPayback=r.recovered&&!projection[i-1]?.recovered;
            return (
              <div key={r.year} style={{flex:1,height:"100%",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-end",gap:4}}>
                <div title={`Año ${r.year}: ${fUSD(r.cum)}`} style={{width:"100%",height:Math.max(pct,3)+"%",borderRadius:"4px 4px 0 0",background:isPayback?C.green:r.recovered?C.greenLight:"#fde8e8",border:isPayback?"1px solid "+C.green:"none",transition:"height 0.4s"}}/>
                {(r.year===1||r.year%5===0)&&<span style={{fontSize:9,color:C.textMuted}}>{r.year}</span>}
              </div>
            );
          })}
        </div>
        {pbYear&&<div style={{background:C.greenLight,borderRadius:12,padding:"12px 16px"}}><span style={{color:C.green,fontWeight:600,fontSize:13}}>✓ Recupero en año {pbYear} · TIR {fPct(irr)} anual · Neto {fUSD(netInc)}/mes</span></div>}
      </div>

      <div style={{...S.card,padding:0,overflow:"hidden",marginBottom:18}}>
        <div style={{padding:"18px 24px",borderBottom:"1px solid "+C.border}}><div style={{fontSize:15,fontWeight:700}}>Tabla de flujo de caja</div></div>
        <div style={{maxHeight:280,overflowY:"auto"}}>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
            <thead style={{position:"sticky",top:0,background:C.bg}}>
              <tr style={{borderBottom:"1px solid "+C.border}}>
                {["Año","Ingresos","Egresos","Neto","Acumulado"].map(h=><th key={h} style={{padding:"10px 18px",textAlign:"left",fontSize:11,color:C.textMuted,fontWeight:600,letterSpacing:"0.4px",textTransform:"uppercase"}}>{h}</th>)}
              </tr>
            </thead>
            <tbody>
              {projection.map(r=>{
                const isPayback=r.recovered&&!projection[r.year-2]?.recovered;
                return (
                  <tr key={r.year} style={{borderBottom:"1px solid "+C.border,background:isPayback?C.greenLight:"transparent"}}>
                    <td style={{padding:"10px 18px",color:C.textSec}}>Año {r.year}</td>
                    <td style={{padding:"10px 18px",color:C.green,fontWeight:500}}>{fUSD(r.inc)}</td>
                    <td style={{padding:"10px 18px",color:C.red,fontWeight:500}}>−{fUSD(r.exp)}</td>
                    <td style={{padding:"10px 18px",fontWeight:600}}>{fUSD(r.net)}</td>
                    <td style={{padding:"10px 18px",fontWeight:700,color:r.cum>=0?C.green:C.red}}>
                      {r.cum>=0?"+":""}{fUSD(r.cum)}
                      {isPayback&&<span style={{marginLeft:10,background:C.green,color:"#fff",fontSize:10,padding:"2px 8px",borderRadius:20,fontWeight:700}}>Recupero</span>}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div style={S.card}>
        <div style={{fontSize:15,fontWeight:700,marginBottom:4}}>Pricing dinámico · Depto 2</div>
        <div style={{fontSize:12,color:C.textSec,marginBottom:18}}>Base $70.000/noche · Fee limpieza $15.000 · Sin comisión</div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(6,1fr)",gap:10}}>
          {pricingExamples.map(({nights,total,perNight,label})=>(
            <div key={nights} style={{background:nights===1?C.yellowLight:nights>=7?C.greenLight:C.bg,border:"1px solid "+(nights===1?C.yellow+"44":nights>=7?C.green+"44":C.border),borderRadius:12,padding:"12px 10px",textAlign:"center"}}>
              <div style={{fontSize:11,color:C.textMuted,marginBottom:6}}>{nights} {nights===1?"noche":"noches"}</div>
              <div style={{fontSize:15,fontWeight:800,color:nights===1?C.yellow:nights>=7?C.green:C.text}}>{fARS(total)}</div>
              <div style={{fontSize:10,color:C.textMuted,marginTop:3}}>{fARS(perNight)}/n</div>
              {(nights===1||nights>=7)&&<div style={{fontSize:9,marginTop:4,fontWeight:700,color:nights===1?C.yellow:C.green}}>{nights===1?"+20%":"-10%"}</div>}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
